def pick(raw, *keys, default=None):
    if not isinstance(raw, dict):
        return default
    for key in keys:
        if key in raw and raw.get(key) not in (None, "", "Unknown", "N/A"):
            return raw.get(key)
    return default




# =========================
# V63 REAL SCORING + FINANCE NORMALIZATION
# =========================
def v63_clean_num(value, default=None):
    try:
        if value is None:
            return default
        if isinstance(value, str):
            text = value.replace("$", "").replace(",", "").replace("%", "").strip()
            if text.lower() in {"", "nan", "none", "null", "n/a", "na", "—", "-"}:
                return default
            value = text
        n = float(value)
        if pd.isna(n):
            return default
        return n
    except Exception:
        return default


def v63_pick(row, *keys, default=None):
    """V64.1: read normalized row first, then Raw payload fallback.
    This prevents blank finance cards when the saved scan keeps values only in Raw.
    """
    if not hasattr(row, "get"):
        return default

    def _valid(value):
        if value is None:
            return False
        if isinstance(value, str) and value.strip().lower() in {"", "nan", "none", "null", "n/a", "na", "—", "-"}:
            return False
        return True

    # 1) normalized dataframe fields
    for key in keys:
        try:
            value = row.get(key)
        except Exception:
            value = None
        if _valid(value):
            return value

    # 2) original raw JSON payload retained by normalize_scan_row
    try:
        raw = row.get("Raw")
    except Exception:
        raw = None
    if isinstance(raw, dict):
        for key in keys:
            value = raw.get(key)
            if _valid(value):
                return value

    return default


def v63_pct_value(value, default=None, cap_abs=300):
    n = v63_clean_num(value, default)
    if n is None:
        return default
    # Many providers store percentages as decimals: 0.165 -> 16.5%.
    if abs(n) <= 2:
        n *= 100
    # Some previous app layers double-multiplied percentages: 12716 -> 127.16.
    if abs(n) > 500:
        n /= 100
    # Extremely large values are usually bad source scaling, not useful finance info.
    if cap_abs is not None and abs(n) > cap_abs:
        return default
    return n


def v63_fmt_pct(value, default="—"):
    n = v63_pct_value(value, None)
    if n is None:
        return default
    return f"{n:.1f}%"


def v63_fmt_num(value, default="—"):
    n = v63_clean_num(value, None)
    if n is None or n == 0:
        return default
    return f"{n:.2f}"


def v63_fmt_money(value, default="—"):
    n = v63_clean_num(value, None)
    if n is None or n == 0:
        return default
    if abs(n) >= 1_000_000_000:
        return f"${n/1_000_000_000:.1f}B"
    if abs(n) >= 1_000_000:
        return f"${n/1_000_000:.1f}M"
    if abs(n) >= 1_000:
        return f"${n/1_000:.1f}K"
    return f"${n:,.2f}"


def v63_finance_metric(row, name):
    mapping = {
        "revenue_growth": ["Revenue Growth", "Revenue Growth %", "Revenue QoQ %", "revenue_growth", "revenue_qoq_pct", "scan_revenue_growth_pct"],
        "earnings_growth": ["Earnings Growth", "EPS Growth", "earnings_growth", "eps_growth"],
        "gross_margin": ["Gross Margin", "gross_margin", "grossMargins", "gross_profit_margin", "grossProfitMarginTTM"],
        "operating_margin": ["Operating Margin", "operating_margin", "operatingMargins", "operating_profit_margin", "operatingProfitMarginTTM"],
        "net_margin": ["Net Margin", "profit_margin", "net_margin", "net_profit_margin", "profitMargins", "netProfitMarginTTM"],
        "free_cash_flow": ["Free Cash Flow", "free_cashflow", "free_cash_flow", "FCF"],
        "operating_cash_flow": ["Operating Cash Flow", "operating_cashflow", "operating_cash_flow", "Op. Cash Flow"],
        "current_ratio": ["Current Ratio", "current_ratio"],
        "debt_to_equity": ["Debt to Equity", "debt_to_equity", "Debt/Equity"],
        "total_debt": ["Total Debt", "total_debt"],
        "cash": ["Cash", "cash_and_equivalents", "total_cash"],
        "ev_sales": ["EV/Sales", "ev_to_sales", "price_to_sales", "Price/Sales"],
        "pe": ["P/E", "pe_ratio", "PE"],
        "forward_pe": ["Forward PE", "forward_pe"],
        "roic": ["ROIC", "roic", "roe"],
        "latest_eps": ["Latest EPS", "latest_eps"],
    }
    return v63_pick(row, *mapping.get(name, [name]), default=None)


def v63_finance_score(row):
    """V63.1 quality score: varied business quality, not a 100-point clone."""
    existing = v63_clean_num(v63_pick(row, "financial_score", "fundamentals_agent_score", "Finance Agent Score", "Quality", "Quality Score"), None)
    rev = v63_pct_value(v63_finance_metric(row, "revenue_growth"), None)
    gross = v63_pct_value(v63_finance_metric(row, "gross_margin"), None)
    net = v63_pct_value(v63_finance_metric(row, "net_margin"), None)
    opm = v63_pct_value(v63_finance_metric(row, "operating_margin"), None)
    fcf = v63_clean_num(v63_finance_metric(row, "free_cash_flow"), None)
    ocf = v63_clean_num(v63_finance_metric(row, "operating_cash_flow"), None)
    cr = v63_clean_num(v63_finance_metric(row, "current_ratio"), None)
    debt_eq = v63_clean_num(v63_finance_metric(row, "debt_to_equity"), None)
    cash = v63_clean_num(v63_finance_metric(row, "cash"), None)
    debt = v63_clean_num(v63_finance_metric(row, "total_debt"), None)

    calculated = 50.0
    if rev is not None: calculated += 9 if rev >= 30 else 7 if rev >= 15 else 4 if rev >= 5 else 1 if rev >= 0 else -8
    if gross is not None: calculated += 9 if gross >= 70 else 7 if gross >= 55 else 4 if gross >= 35 else 1 if gross >= 20 else -5
    if opm is not None: calculated += 8 if opm >= 25 else 6 if opm >= 15 else 3 if opm >= 5 else -7 if opm < 0 else 0
    if net is not None: calculated += 8 if net >= 25 else 6 if net >= 15 else 3 if net >= 5 else -7 if net < 0 else 0
    if fcf is not None: calculated += 6 if fcf > 0 else -7
    if ocf is not None: calculated += 5 if ocf > 0 else -5
    if cr is not None: calculated += 4 if cr >= 1.8 else 2 if cr >= 1.1 else -5
    if debt_eq is not None: calculated += 4 if debt_eq <= 40 else 2 if debt_eq <= 100 else -6 if debt_eq > 180 else 0
    if cash is not None and debt is not None: calculated += 3 if cash >= debt else -3

    calculated = max(25, min(95, calculated))
    if existing is not None and existing > 0:
        # Keep scanner fundamentals signal, but do not let it force every quality score to 100.
        score = existing * 0.60 + calculated * 0.40
    else:
        score = calculated
    return int(round(max(20, min(97, score))))


def v63_quality_score(row):
    return v63_finance_score(row)


def v63_target_upside(row):
    price = v63_clean_num(v63_pick(row, "Price", "price", "current_price", "last_price"), 0) or 0
    scanner_target = v63_clean_num(v63_pick(row, "Target", "AI Fair Value", "target", "ai_base_target"), 0) or 0
    analyst_target = v63_clean_num(v63_pick(row, "Analyst Target", "target_mean_price", "analyst_target_mean"), 0) or 0
    raw = v63_pct_value(v63_pick(row, "Target Upside %", "target_upside_pct", "expected_upside_pct", "upside", "analyst_upside_pct"), None, cap_abs=500)

    scanner_calc = None
    if price > 0 and scanner_target > 0:
        scanner_calc = ((scanner_target - price) / price) * 100
    analyst_calc = None
    if price > 0 and analyst_target > 0:
        analyst_calc = ((analyst_target - price) / price) * 100

    # A repeated exact 30.0% usually means the scanner defaulted to price * 1.30.
    placeholder_30 = (raw is not None and abs(raw - 30.0) < 0.05) or (scanner_calc is not None and abs(scanner_calc - 30.0) < 0.15)
    if placeholder_30 and analyst_calc is not None and -80 <= analyst_calc <= 250:
        return analyst_calc
    if raw is not None and not placeholder_30:
        return raw
    if scanner_calc is not None and -90 <= scanner_calc <= 300 and not placeholder_30:
        return scanner_calc
    if analyst_calc is not None and -80 <= analyst_calc <= 250:
        return analyst_calc
    if scanner_calc is not None:
        return scanner_calc
    return 0.0


def v63_opportunity_score(row):
    base = v63_clean_num(v63_pick(row, "Final Conviction", "conviction", "conviction_score", "ai_score", "Score", "score"), 60) or 60
    upside = v63_target_upside(row)
    rr = v63_clean_num(v63_pick(row, "Risk/Reward", "risk_reward"), 0) or 0
    rsi = v63_clean_num(v63_pick(row, "RSI", "rsi"), 50) or 50
    trend20 = v63_clean_num(v63_pick(row, "20D %", "twenty_day_pct", "return_1m_pct"), 0) or 0
    trend5 = v63_clean_num(v63_pick(row, "5D %", "five_day_pct"), 0) or 0
    volume = v63_clean_num(v63_pick(row, "Volume Ratio", "volume_ratio"), 1) or 1
    analyst = v56_analyst_score(row) if "v56_analyst_score" in globals() else 50
    quality = v63_quality_score(row)

    upside_score = max(0, min(100, 45 + upside * 1.15))
    rr_score = 48 + min(rr, 7) * 7 if rr else 50
    momentum_score = 50
    if trend20 > 20: momentum_score += 22
    elif trend20 > 10: momentum_score += 15
    elif trend20 > 3: momentum_score += 7
    elif trend20 < -10: momentum_score -= 14
    if trend5 > 7: momentum_score += 8
    elif trend5 < -5: momentum_score -= 5
    if 45 <= rsi <= 68: momentum_score += 7
    elif rsi > 75: momentum_score -= 12
    elif rsi < 35: momentum_score -= 6
    if volume >= 1.3: momentum_score += 5

    score = base * 0.20 + upside_score * 0.30 + rr_score * 0.18 + momentum_score * 0.17 + analyst * 0.08 + quality * 0.07
    return int(round(max(20, min(98, score))))


def v63_recommendation(row):
    raw = str(v63_pick(row, "Verdict", "Final Verdict", "Recommendation", "Action", default="") or "").upper()
    opp = v63_opportunity_score(row)
    q = v63_quality_score(row)
    upside = v63_target_upside(row)
    rr = v63_clean_num(v63_pick(row, "Risk/Reward", "risk_reward"), 0) or 0
    if "AVOID" in raw or "SELL" in raw:
        return "🔴 AVOID"
    if opp >= 84 and q >= 72 and upside >= 12 and (rr == 0 or rr >= 1.5):
        return "✅ BUY NOW"
    if opp >= 75 and upside >= 6:
        return "🟡 WATCHLIST"
    if opp >= 65:
        return "👀 MONITOR"
    return "🔴 AVOID"


def v63_score_label(score):
    score = int(round(v63_clean_num(score, 0) or 0))
    if score >= 85: return "Excellent"
    if score >= 75: return "Strong"
    if score >= 65: return "Good"
    if score >= 55: return "Developing"
    return "Speculative"


def v63_progress_html(label, score, subtitle=""):
    score = int(round(v63_clean_num(score, 0) or 0))
    pct = max(0, min(100, score))
    color = "#22C55E" if pct >= 80 else "#38BDF8" if pct >= 70 else "#F59E0B" if pct >= 55 else "#EF4444"
    return f"""
    <div style='margin:10px 0 14px 0;'>
      <div style='display:flex;justify-content:space-between;gap:12px;font-weight:850;color:#F8FAFC;'>
        <span>{label}</span><span>{pct}/100 · {v63_score_label(pct)}</span>
      </div>
      <div style='height:10px;border-radius:99px;background:rgba(148,163,184,.18);margin-top:7px;overflow:hidden;'>
        <div style='height:10px;width:{pct}%;background:{color};border-radius:99px;'></div>
      </div>
      <div style='color:#94A3B8;font-size:12px;margin-top:4px;'>{subtitle}</div>
    </div>
    """

def read_json_file(path: Path):
    if not path.exists():
        return []
    try:
        with path.open("r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return []


def read_state():
    data = read_json_file(STATE_FILE)
    return data if isinstance(data, dict) else {}


def normalize_rows(data):
    if isinstance(data, dict):
        if isinstance(data.get("rows"), list):
            return data["rows"]
        if isinstance(data.get("data"), list):
            return data["data"]
        if isinstance(data.get("symbols"), list):
            return [{"symbol": s} for s in data["symbols"]]
        return []
    if isinstance(data, list):
        return data
    return []


