# =========================
# V52.1 EARNINGS WATCH CLEANUP
# =========================
# Purpose: keep the top Earnings Watch customer-friendly by removing OTC,
# foreign ordinary, preferred, warrant, rights, and obscure rows that make
# the dashboard look noisy or broken. If no recognizable U.S.-listed rows
# remain, show a clean fallback risk-check instead of bad data.

APP_VERSION = "V53 Client Earnings Brief"


def v521_clean_earnings_symbol(sym):
    sym = str(sym or "").upper().strip()
    if not sym:
        return ""
    return sym


def v521_is_customer_friendly_us_ticker(sym, company=""):
    import re
    sym = v521_clean_earnings_symbol(sym)
    company = str(company or "").strip()
    upper_company = company.upper()

    if not sym:
        return False

    # Remove exchange-suffixed international listings and non-common-share formats.
    if "." in sym or "/" in sym or " " in sym:
        return False
    if "-" in sym:
        return False

    # Only plain alphabetic U.S.-style symbols in the default paid-customer view.
    if not re.match(r"^[A-Z]{1,5}$", sym):
        return False

    # Remove most OTC / foreign ordinary / ADR-like obscure endings when 5 letters.
    # Examples caught: DIGBF, TGVSF, MTYFF, RYKKY, EMSHF, JNDOF, MHGUP.
    if len(sym) == 5 and sym[-1] in {"F", "Y", "P", "Q", "W", "R", "U"}:
        return False

    # Remove empty company rows. Blank company fields look broken to customers.
    if not company or company in {"-", "N/A", "NONE", "NULL"}:
        return False

    # Remove security types that are not useful for a retail earnings watch.
    blocked_company_terms = [
        "PREFERRED", "PREF", "WARRANT", "RIGHT", "UNIT", "UNITS",
        "DEPOSITARY", "NOTE", "BOND", "ETF", "FUND", "TRUST SERIES"
    ]
    if any(term in upper_company for term in blocked_company_terms):
        return False

    return True


def v521_clean_earnings_rows(raw_rows, max_rows=15):
    out = []
    seen = set()
    for r in raw_rows or []:
        if not isinstance(r, dict):
            continue
        sym = v521_clean_earnings_symbol(r.get("symbol") or r.get("ticker") or r.get("Ticker"))
        company = v51_text(r.get("company") or r.get("companyName") or r.get("name") or r.get("Company"), "") if "v51_text" in globals() else str(r.get("company") or r.get("companyName") or r.get("name") or r.get("Company") or "")
        if not v521_is_customer_friendly_us_ticker(sym, company):
            continue
        if sym in seen:
            continue
        seen.add(sym)
        out.append({
            "Date": v51_text(r.get("date") or r.get("Date"), "")[:10] if "v51_text" in globals() else str(r.get("date") or r.get("Date") or "")[:10],
            "Ticker": sym,
            "Company": company,
            "Time": v51_text(r.get("time") or r.get("hour") or r.get("when") or r.get("Time"), "") if "v51_text" in globals() else str(r.get("time") or r.get("hour") or r.get("when") or r.get("Time") or ""),
            "EPS Est": v51_num(r.get("epsEstimated") or r.get("epsEstimate") or r.get("estimatedEps") or r.get("EPS Est")) if "v51_num" in globals() else r.get("epsEstimated") or r.get("epsEstimate") or r.get("estimatedEps") or r.get("EPS Est") or "",
            "Revenue Est": v51_money(r.get("revenueEstimated") or r.get("revenueEstimate")) if ("v51_money" in globals() and (r.get("revenueEstimated") or r.get("revenueEstimate"))) else (r.get("Revenue Est") or "N/A"),
        })
        if len(out) >= max_rows:
            break
    return out


def v521_fallback_earnings_rows(days=14):
    today = dt.date.today()
    return [
        {
            "Date": str(today),
            "Focus": "No major recognizable U.S. earnings confirmed today",
            "Why It Matters": "The connected source did not return clean, customer-relevant U.S. company rows. This is better than showing obscure OTC or foreign securities."
        },
        {
            "Date": str(today + dt.timedelta(days=3)),
            "Focus": "Upcoming U.S. earnings window",
            "Why It Matters": "Before entering a position, check whether the company reports soon because earnings can override technical signals and analyst targets."
        },
        {
            "Date": str(today + dt.timedelta(days=7)),
            "Focus": "7-day earnings risk check",
            "Why It Matters": "If earnings are close, consider smaller sizing or waiting for results unless the thesis is long term."
        },
    ]


def v51_earnings_calendar(days=14):
    today = dt.date.today()
    end = today + dt.timedelta(days=days)
    rows, status, diag = ([], "unavailable", [])
    try:
        if "v5082_stable_rows" in globals():
            rows, status, diag = v5082_stable_rows(
                "earnings-calendar",
                {"from": today.isoformat(), "to": end.isoformat(), "limit": 750},
            )
    except Exception as e:
        diag = [f"earnings calendar error: {e}"]

    cleaned = v521_clean_earnings_rows(rows, max_rows=15)
    fallback = False
    if not cleaned:
        fallback = True
        cleaned = v521_fallback_earnings_rows(days=days)

    try:
        diag = list(diag or [])
        diag.append(f"V52.1 earnings cleanup: raw_rows={len(rows or [])}; displayed_rows={len(cleaned)}; fallback={fallback}")
    except Exception:
        pass

    return {"rows": cleaned, "status": status, "diagnostics": diag, "fallback": fallback}


def v511_earnings_rows(days=14):
    try:
        data = v51_earnings_calendar(days=days)
        return data.get("rows") or [], data.get("diagnostics") or [], bool(data.get("fallback"))
    except Exception as e:
        return v521_fallback_earnings_rows(days=days), [f"V52.1 earnings wrapper error: {e}"], True




# =========================
# V55 CLIENT DEMO POLISH
# =========================
# Fixes customer-facing clipping and improves ranked table trust:
# - Final recommendation no longer clips "Buy Now" on wide/desktop view.
# - Ranked Ideas now separates Opportunity from Quality.
# - Adds Classification and Why Ranked so equal scores still make sense.
# - Removes confusing Execution Checks and repeated raw score language from client table.

APP_VERSION = "V55 Client Demo Polish"


def v54_num(x, default=0.0):
    try:
        if x is None:
            return default
        if isinstance(x, str):
            x = x.replace('$', '').replace(',', '').replace('%', '').strip()
            if x in {'', 'N/A', 'None', 'nan'}:
                return default
        return float(x)
    except Exception:
        return default


def v54_int(x, default=0):
    try:
        return int(round(v54_num(x, default)))
    except Exception:
        return default


def v54_money(x):
    n = v54_num(x, None)
    if n is None or n == 0:
        return "N/A"
    return f"${n:,.2f}"


def v54_pct(x):
    n = v54_num(x, None)
    if n is None:
        return "N/A"
    return f"{n:.1f}%"


def v55_is_admin():
    return (st.session_state.get("role") == "admin") or (st.session_state.get("user_role") == "admin")


def v55_sources_reviewed_card():
    """Client-safe source summary. Avoids exposing provider names/endpoints in viewer mode."""
    st.markdown("### Sources Reviewed")
    st.markdown(
        "✓ Financial statements  \n"
        "✓ Analyst estimates and ratings  \n"
        "✓ Institutional and insider activity  \n"
        "✓ News and catalyst signals  \n"
        "✓ Technical indicators and risk/reward"
    )
    st.caption("Data Confidence: High when multiple independent signals support the thesis. Provider diagnostics remain admin-only.")


def v54_clean_verdict(verdict):
    v = str(verdict or "Review").replace("✅", "").replace("🟢", "").strip()
    u = v.upper()
    if "BUY" in u:
        return "BUY NOW" if "NOW" in u else "BUY"
    if "HOLD" in u:
        return "HOLD"
    if "AVOID" in u or "SELL" in u:
        return "AVOID"
    if "WATCH" in u:
        return "WATCH"
    return v[:24] or "Review"


def v54_quality_from_row(row):
    # Prefer V51 quality logic when available; otherwise use financial health fallback.
    try:
        rep = v51_report(row)
        status = v51_top_choice_status(rep)
        q = v54_num(status.get("quality"), None)
        if q is not None:
            return max(0, min(100, q))
    except Exception:
        pass
    for key in ["Quality Score", "Financial Health Score", "Financial Health", "fundamental_score", "Fundamental Score"]:
        try:
            if key in row and row.get(key) is not None:
                q = v54_num(row.get(key), None)
                if q is not None:
                    return max(0, min(100, q))
        except Exception:
            pass
    return 50


def v54_opportunity_from_row(row):
    for key in ["Opportunity Score", "Final Conviction", "Investment Score", "Score"]:
        try:
            if key in row and row.get(key) is not None:
                return max(0, min(100, v54_num(row.get(key), 0)))
        except Exception:
            pass
    return 0


def v54_classification(row, opportunity=None, quality=None):
    opportunity = v54_opportunity_from_row(row) if opportunity is None else opportunity
    quality = v54_quality_from_row(row) if quality is None else quality
    upside = v54_num(row.get("Target Upside %"), 0) if hasattr(row, 'get') else 0
    analyst = str(row.get("Analyst Support", "") if hasattr(row, 'get') else "").lower()
    verdict = v54_clean_verdict(row.get("Verdict", row.get("Agent Verdict", "")) if hasattr(row, 'get') else "")

    if verdict in {"AVOID", "WATCH"}:
        return "👀 Watchlist"
    if quality >= 85 and opportunity >= 88:
        return "🏆 Top Choice"
    if quality >= 75 and opportunity >= 82:
        return "✅ Quality Growth"
    if upside >= 100 and quality < 70:
        return "🚀 Speculative Growth"
    if "bullish" in analyst and opportunity >= 80:
        return "📈 Analyst Favorite"
    if opportunity >= 80:
        return "⚡ Opportunity"
    return "👀 Research Candidate"


def v54_analyst_view(raw):
    txt = str(raw or "").strip()
    score = None
    import re
    m = re.search(r"(\d{1,3})\s*/\s*100", txt)
    if m:
        score = int(m.group(1))
    elif "(" in txt and "/100" in txt:
        try:
            score = int(txt.split("(")[-1].split("/")[0])
        except Exception:
            score = None

    low = txt.lower()
    if score is not None:
        if score >= 80:
            return "🔥 Strong"
        if score >= 65:
            return "✅ Positive"
        if score >= 50:
            return "⚪ Mixed"
        return "🔴 Weak"
    if "bullish" in low:
        return "🔥 Strong"
    if "constructive" in low or "positive" in low:
        return "✅ Positive"
    if "weak" in low or "bear" in low:
        return "🔴 Weak"
    return "⚪ Mixed"


def v54_news_view(raw):
    low = str(raw or "").lower()
    if any(x in low for x in ["bullish", "positive", "strong"]):
        return "🟢 Positive"
    if any(x in low for x in ["bearish", "negative", "weak"]):
        return "🔴 Negative"
    return "⚪ Neutral"


def v54_why_ranked(row, opportunity=None, quality=None):
    """Plain-English reason designed for customer-facing ranked tables.
    Avoids repeated generic phrasing and explains the tradeoff behind the rank.
    """
    opportunity = v54_opportunity_from_row(row) if opportunity is None else opportunity
    quality = v54_quality_from_row(row) if quality is None else quality
    upside = v54_num(row.get("Target Upside %"), 0) if hasattr(row, 'get') else 0
    analyst_raw = row.get("Analyst Support", "") if hasattr(row, 'get') else ""
    analyst_view = v54_analyst_view(analyst_raw)

    if quality >= 82 and opportunity >= 88 and upside >= 40:
        return "Strong quality with attractive upside"
    if quality >= 75 and opportunity >= 85:
        return "Quality growth setup with favorable entry"
    if quality < 65 and upside >= 100:
        return "Large upside, but weaker financial quality"
    if quality < 65 and opportunity >= 90:
        return "High-opportunity setup with elevated quality risk"
    if "Strong" in analyst_view and upside >= 50:
        return "Analyst-backed upside setup"
    if upside >= 75:
        return "Attractive upside with actionable setup"
    if opportunity >= 90:
        return "High-opportunity setup with favorable risk/reward"
    if quality >= 80:
        return "Quality profile supports the ranking"
    return "Actionable setup; review full report first"


def v493_table_rows_fast(df, limit=60):
    rows = []
    if df is None or df.empty:
        return rows

    for _, row in df.head(limit).iterrows():
        try:
            price = v54_num(row.get("Price"), 0)
            target = v54_num(row.get("AI Fair Value") or row.get("Analyst Target"), 0)
            upside = v54_num(row.get("Target Upside %"), 0)
            stop = v54_num(row.get("Stop Loss"), 0)
            verdict, checks, passed = v50_ready_verdict(row)
            opportunity = v54_opportunity_from_row(row)
            quality = v54_quality_from_row(row)

            rows.append({
                "Ticker": str(row.get("Ticker", "")).strip(),
                "Company": str(row.get("Company", "")).strip(),
                "Verdict": v54_clean_verdict(verdict),
                "Classification": v54_classification(row, opportunity, quality),
                "Opportunity": v54_int(opportunity),
                "Quality": v54_int(quality),
                "Upside": v54_pct(upside),
                "Price": v54_money(price),
                "Entry": str(row.get("Entry Range", "N/A")),
                "Stop": v54_money(stop) if stop else "N/A",
                "Target": v54_money(target),
                "Analyst View": v54_analyst_view(row.get("Analyst Support", "")),
                "Why Ranked": v54_why_ranked(row, opportunity, quality),
            })
        except Exception:
            continue
    return rows


def render_v49_ready_section(df):
    rows = v493_table_rows_fast(df, limit=80)
    ready = [x for x in rows if x.get("Verdict") in ["BUY NOW", "BUY", "BUY GRADUALLY"]]

    with st.container(border=True):
        st.markdown("### 🔥 Ready to Execute")
        st.caption("Fast scan-only view. News is kept inside each detailed report; this table focuses on opportunity, quality, analyst view, entry discipline, and why the idea ranked.")
        if ready:
            out = pd.DataFrame(ready)
            if {"Opportunity", "Quality"}.issubset(out.columns):
                out = out.sort_values(["Opportunity", "Quality"], ascending=False)
            preferred_cols = [
                "Ticker", "Company", "Verdict", "Classification", "Opportunity", "Quality",
                "Upside", "Price", "Entry", "Stop", "Target", "Analyst View", "Why Ranked"
            ]
            cols = [c for c in preferred_cols if c in out.columns] + [c for c in out.columns if c not in preferred_cols]
            st.dataframe(out[cols].head(25), use_container_width=True, hide_index=True)
        else:
            st.info("No stock currently meets BUY NOW / BUY GRADUALLY thresholds from the persisted scan data.")


def render_v51_final_recommendation(row):
    report = v51_report(row)
    ticker = v51_text(report.get("ticker") or report.get("Ticker"), "")
    ws = v51_wallstreet_pack(ticker) if ticker else {}
    target = v51_target_pack(report, ws)
    status = v51_top_choice_status(report, ws)
    thesis = v51_investment_thesis(report, ws, target)

    verdict_display = v54_clean_verdict(status.get("label", "Review"))
    opportunity = v54_int(status.get("opportunity", 0))
    quality = v54_int(status.get("quality", 0))
    confidence = v54_int(status.get("confidence", 0))

    with st.container(border=True):
        st.markdown("## 🧠 Final Recommendation")

        c1, c2, c3, c4 = st.columns([1.5, 1, 1, 1])
        with c1:
            st.markdown("**Recommendation**")
            if "BUY" in verdict_display.upper():
                st.markdown("## ✅ Buy Now")
            elif "HOLD" in verdict_display.upper():
                st.markdown("## ⚪ Hold")
            elif "AVOID" in verdict_display.upper() or "SELL" in verdict_display.upper():
                st.markdown("## 🔴 Avoid")
            elif "WATCH" in verdict_display.upper():
                st.markdown("## 👀 Watch")
            else:
                st.markdown(f"## {verdict_display}")
        with c2:
            st.markdown("**Opportunity**")
            st.markdown(f"## {opportunity}/100")
        with c3:
            st.markdown("**Quality**")
            st.markdown(f"## {quality}/100")
        with c4:
            st.markdown("**Confidence**")
            st.markdown(f"## {confidence}/100")

        st.markdown(f"**Classification:** {status['classification']}")

        st.info(
            f"""
### Customer Summary
This stock is currently rated **{verdict_display}**.

The **Opportunity Score** is **{opportunity}/100**, which measures upside potential, setup strength, analyst support, and risk/reward.

The **Quality Score** is **{quality}/100**, which measures the strength and durability of the underlying business. A stock can have high opportunity but still fail Top Choice status if financial quality is not strong enough.

The **Confidence Score** is **{confidence}/100**, which reflects how much supporting evidence the dashboard has behind the recommendation.
"""
        )

        v55_sources_reviewed_card()

        if status.get("blocks"):
            st.markdown("### Why This Is Not A Top Choice")
            st.warning(
                f"""
Although this stock may show attractive upside, its **Quality Score ({quality}/100)** or supporting checks are below the dashboard's Top Choice threshold.

This means the idea may still be investable, but it is not currently considered a flagship-quality opportunity. Customers should treat it as an opportunity that requires more attention to position sizing, execution risk, and financial durability.
"""
            )
            for b in status["blocks"]:
                st.markdown(f"⚠️ {b}")

        st.markdown("## 🎯 Investment Thesis")
        for line in thesis:
            st.markdown(f"• {line}")

        if target.get("available"):
            st.markdown(
                f"**Target Discipline:** Consensus target is {v51_money(target.get('consensus'))}; "
                f"AI fair value range is {v51_money(target.get('fair_low'))}–{v51_money(target.get('fair_high'))}; "
                f"bull case is {v51_money(target.get('bull'))}; bear case is {v51_money(target.get('bear'))}."
            )

